python - <<'PY'
import json, math
from pathlib import Path
obj=json.loads(Path('benchmark/source_data.json').read_text())
# build dicts
wsd={d['country']:d for d in obj['water_supply_demand']['data']}
pc={d['country']:d for d in obj['per_capita_freshwater']['data']}
gw={d['country']:d for d in obj['groundwater_extraction']['data']}
# precip trend: percent change 1990s->2010s
prec={}
for row in obj['precipitation_trends']['data']:
    prec.setdefault(row['country'], {})[row['decade']]=row['mean_precip_mm']
trend={c:(prec[c]['2010s']-prec[c]['1990s'])/prec[c]['1990s']*100 for c in prec}
# print combined table
countries=list(wsd.keys())
print('country\tsupply/demand\tgw_ratio\tper_capita\tprec_%chg')
for c in countries:
    print(f"{c}\t{wsd[c]['supply_demand_ratio']}\t{gw[c]['extraction_recharge_ratio']}\t{pc[c]['per_capita_m3']}\t{trend[c]:.1f}")
PY

